"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["15084"],{4552(e){e.exports=JSON.parse('{"id":"FIN-875","slug":"non-operating-asset","term":"Non-Operating Asset","also_known_as":[],"difficulty":"Intermediate","definition":"A non-operating asset is an asset a company owns that is not needed to run its core business, such as excess cash, investments in other companies or unused land.","explanation":["When analysts value a company based on the cash flows from its main operations, those cash flows do not reflect the value of assets that sit outside the business. Non-operating assets must therefore be valued separately and added to the value of the operations.","Common examples include cash beyond what the business needs for daily operations, marketable securities, minority stakes in other companies, property held for investment rather than used by the business, and surplus land or buildings that could be sold.","For example, a manufacturing company\'s operations might be worth 500 million based on discounted cash flows. If it also owns a stake in another company worth 40 million and unused land worth 10 million, these non-operating assets add 50 million, bringing the total value to 550 million, before subtracting debt.","Identifying non-operating assets helps avoid undervaluing a company. It also helps analysts compare companies fairly, since operating ratios such as return on capital can be distorted if non-operating assets are mixed in with operating ones."],"note":"","total":1500,"prev":{"slug":"non-fungible-token","term":"Non-Fungible Token (NFT)"},"next":{"slug":"noncontrolling-interest","term":"Noncontrolling Interest"}}')}}]);